<script setup lang="ts">
import { CalendarDays, Clock } from 'lucide-vue-next'
definePageMeta({layout:'student'}); const config=useRuntimeConfig(); const token=useCookie<string|null>('token'); const {user}=useAuth(); const events=ref<any[]>([])
const fmt=(v:string)=>new Date(v).toLocaleString('vi-VN'); onMounted(async()=>events.value=await $fetch('/calendar/my-exams',{baseURL:config.public.apiBase,headers:{Authorization:`Bearer ${token.value}`,'x-user-id':String(user.value?.id),'x-user-role':String(user.value?.role)}}) as any[])
</script><template><section><div class="mb-6"><h2 class="text-2xl font-bold text-slate-900">Lịch thi</h2><p class="text-slate-500">Theo dõi các kỳ thi sắp diễn ra theo thời gian.</p></div><div class="grid gap-4 md:grid-cols-2"><article v-for="e in events" :key="e.id" class="surface-card card-hover p-5"><div class="flex gap-3"><CalendarDays class="text-blue-600"/><div><h3 class="font-semibold text-lg">{{e.title}}</h3><p class="mt-2 text-sm text-slate-600"><Clock class="inline w-4 h-4"/> {{fmt(e.start_time)}} — {{fmt(e.end_time)}}</p><NuxtLink :to="`/student/exam/${e.id}`" class="mt-4 inline-flex btn-primary">Xem bài thi</NuxtLink></div></div></article></div><div v-if="!events.length" class="surface-card p-10 text-center text-slate-500">Chưa có lịch thi.</div></section></template>